import { Table, ReferenceColumn } from '../../db'

export const sys_ws_header_map = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    display: 'web_service_header',
    extends: 'sys_metadata',
    label: 'Scripted REST Header Association',
    name: 'sys_ws_header_map',
    schema: {
        web_service_header: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'The header to associate with the resource',
                    label: 'API request header',
                    plural: 'API request headers',
                },
            ],
            mandatory: true,
            referenceTable: 'sys_ws_header',
            referenceQual:
                "javascript:'web_service_definition=' + current.web_service_operation.web_service_definition",
        }),

        web_service_operation: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: [
                {
                    hint: 'The resource to associate with the header',
                    label: 'API resource',
                    plural: 'API resources',
                },
            ],
            mandatory: true,
            referenceTable: 'sys_ws_operation',
        }),
    },
    textIndex: true,
})
